    try {
      key = await this.aqvisionAgencyApiClient.rotateStreamKey(candidate.id);
      this.assertAqpLeaseOwned(lease);
    } catch (error) {
      this.assertAqpLeaseOwned(lease);
      try {
        key = await this.aqvisionAgencyApiClient.createStreamKey({ app: 'live', stream: key.stream });
        this.assertAqpLeaseOwned(lease);
      } catch (reactivateError) {
        // Vẫn lỗi: bỏ qua key này, thử key rảnh kế tiếp.
