      return payload;
    } catch (error) {
      if (error instanceof AqvisionAgencyApiException) throw error;
      throw new AqvisionAgencyApiException(
        `Không kết nối được Agency API khi gọi ${method} ${path}.`,
        null,
        method !== 'GET',
      );
    } finally {
