      );

    const result = await makeClient().createStreamKey({ app: 'live', stream: 'cam_1' });

    expect(result).toEqual({
      id: 'key-1',
      app: 'live',
      stream: 'cam_1',
      status: 'Offline',
      push,
    });
    expect(fetchMock).toHaveBeenNthCalledWith(
      1,
      'https://media.aqvision.net/api/v1/auth/token',
