  it('reuses the token until the vendor expiry timestamp', async () => {
    fetchMock
      .mockResolvedValueOnce(
        jsonResponse({
          code: 200,
          data: { token: TOKEN, expiresAt: new Date(now + 3_600_000).toISOString() },
