        ) => operation({ cameraId: 'camera-1', isOwned: () => true }),
      ) as unknown as LivestreamHealthQueue['runWithStreamNameLock'],
      // Pool lock cho kho key chung: test chạy thẳng operation (đơn instance).
      runWithAqpStreamKeyPoolLock: jest.fn(
        async (
          _cameraId: string,
          operation: (lease: { cameraId: string; isOwned: () => boolean }) => Promise<unknown>,
