      } as unknown as LivestreamRepository['recordingPlaybacksRepo'],
      findPublishersActiveWithinWindow: jest.fn(async () => []),
      updateCameraIdentityState: jest.fn(async () => true),
      updateCameraStatus: jest.fn(async () => true),
      countActiveCameraPublisherLeases: jest.fn(async () => 0),
    };
    const service = new LivestreamService(
      {
        get: ((key: string) => (options.pushConfig ?? {})[key] ?? fallbackEnvValue(key)) as unknown as {
          get<T>(key: string, defaultValue?: T): T;
        },
      },
      repositoryMock,
      livestreamHealthQueue as unknown as LivestreamHealthQueue,
      aqvisionPublishService,
      agencyClient,
      {
        isMediaOnline:
          options.isMediaOnline ??
