      } as never,
      {
        repo: { findOne: jest.fn(async () => ({ reportersActive: 0 })) },
      } as never,
      { [matchVenueRepoSymbol]: { repo: { findOne: jest.fn(async () => null) } } } as never,
      { [tournamentConfigRepoSymbol]: { repo: { findOne: jest.fn(async () => null) } } } as never,
      { [matchLivestreamRepoSymbol]: {
        repo: { findOne: jest.fn(async () => null) },
        updateChanges: jest.fn(async () => true),
        applyDecorationPayload: jest.fn(async () => true),
      } } as never,
      { publish: jest.fn(async () => true) } as never,
      redisState as never,
