  }

  it('không có endpoint DELETE key nào trên agency client (policy dùng lại kho 10 key)', () => {
    const { agencyClient } = makeService();
    // Thu hồi key = rotate + gỡ liên kết local; key đã thu hồi vẫn tính vào giới hạn 10.
    expect(agencyClient).not.toHaveProperty('deleteStreamKey');
    expect(typeof (agencyClient as Record<string, unknown>).rotateStreamKey).toBe('function');
  });

  it('tạo key mới qua POST khi kho rỗng (và đọc kho trước bằng listStreamKeys)', async () => {
    const { service, agencyClient, repository, readCameraAqpStreamKey } = makeService();

    const response = await service.createCameraAqpStreamKey(
      createCameraAqpStreamKeyInput as never,
      opUser,
    );

    expect(response).toEqual(await readCameraAqpStreamKey());
    expect(agencyClient.listStreamKeys).toHaveBeenCalledTimes(1);
    expect(agencyClient.createStreamKey).toHaveBeenCalledTimes(1);
    expect(agencyClient.createStreamKey).toHaveBeenCalledWith({
      app: 'live',
