  });

  it('không POST khi không đọc được danh sách kho (fail closed trước khi tạo key)', async () => {
    const { service, agencyClient } = makeService({
      listStreamKeys: jest.fn().mockRejectedValue(
        new AqvisionAgencyApiException({ message: 'list failed' }, 'GET /stream-keys', 503),
      ) as AqvisionAgencyApiClient['listStreamKeys'],
