    await expect(
      service.createCameraAqpStreamKey(createCameraAqpStreamKeyInput as never, opUser),
    ).rejects.toThrow(ServiceUnavailableException);
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
