  it('dùng lại key rảnh trong kho (rename → rotate → gắn) thay vì POST tạo mới', async () => {
    const freeKey: AqvisionAgencyStreamKey = {
      id: 'free-1',
      app: 'live',
      stream: 'camera_free_1',
      status: 'Active',
      push: publishConfigOf('free-old-secret'),
    };
    const { service, agencyClient, repository, readCameraAqpStreamKey } = makeService({
      listStreamKeys: jest.fn(async () => [freeKey]) as AqvisionAgencyApiClient['listStreamKeys'],
      getStreamKey: jest.fn(async () => freeKey) as AqvisionAgencyApiClient['getStreamKey'],
