    expect(agencyClient.getStreamKey).toHaveBeenCalledWith('free-2');
    expect(agencyClient.updateStreamKey).not.toHaveBeenCalled();
    expect(agencyClient.rotateStreamKey).not.toHaveBeenCalled();
    expect(repository.isAqpStreamKeyIdInUse).toHaveBeenCalledWith('used-1');
    expect(repository.isAqpStreamKeyIdInUse).toHaveBeenCalledWith('free-2');
  });

  it('chỉ dùng lại key đúng namespace của môi trường (AQVISION_STREAM_NAME_PREFIX)', async () => {
    const foreignKey: AqvisionAgencyStreamKey = {
      id: 'legacy-1',
      app: 'live',
      stream: 'camera_legacy_1', // tiền tố mặc định `camera_` — khác namespace `prod_camera_`
      status: 'Active',
      push: publishConfigOf('legacy-secret'),
    };
    const ownKey: AqvisionAgencyStreamKey = {
      id: 'prod-1',
      app: 'live',
      stream: 'prod_camera_free_1',
      status: 'Active',
      push: publishConfigOf('prod-free-secret'),
    };
    const { service, agencyClient } = makeService({
      pushConfig: { AQVISION_STREAM_NAME_PREFIX: 'prod_camera_' },
      listStreamKeys: jest.fn(async () => [foreignKey, ownKey]) as AqvisionAgencyApiClient['listStreamKeys'],
      isAqpStreamKeyIdInUse: jest.fn(async () => false) as LivestreamRepository['isAqpStreamKeyIdInUse'],
      getStreamKey: jest.fn(async () => ownKey) as AqvisionAgencyApiClient['getStreamKey'],
    });

    // Camera đang ở namespace `prod_camera_` (tên mới đặt theo prefix env).
    await service.createCameraAqpStreamKey(
      {
        ...createCameraAqpStreamKeyInput,
        camera: { ...createCameraAqpStreamKeyInput.camera, streamName: 'prod_camera_abc' },
      } as never,
      opUser,
    );

    // Key `camera_legacy_1` ngoài namespace: không GET, không gắn — chỉ key prod_camera_ được dùng.
    expect(agencyClient.getStreamKey).toHaveBeenCalledTimes(1);
    expect(agencyClient.getStreamKey).toHaveBeenCalledWith('prod-1');
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
    expect(agencyClient.updateStreamKey).toHaveBeenCalledWith(
      'prod-1',
      { stream: 'prod_camera_abc' },
      'PATCH',
    );
  });

  it('key đã thu hồi trước đây: rotate thành công → đổi tên → rotate lấy push mới → gắn', async () => {
    const revokedKey: AqvisionAgencyStreamKey = {
      id: 'free-9',
      app: 'live',
      stream: 'camera_old_9',
      status: 'Active',
      push: null,
    };
    const { service, agencyClient, repository } = makeService({
      listStreamKeys: jest.fn(async () => [revokedKey]) as AqvisionAgencyApiClient['listStreamKeys'],
      getStreamKey: jest.fn(async () => revokedKey) as AqvisionAgencyApiClient['getStreamKey'],
      updateStreamKey: jest.fn(async () => ({ ...revokedKey, stream: 'camera_abc', push: null })) as AqvisionAgencyApiClient['updateStreamKey'],
      rotateStreamKey: jest
        .fn()
        .mockResolvedValueOnce({ ...revokedKey, push: publishConfigOf('recovered-secret') })
        .mockResolvedValueOnce({ ...revokedKey, stream: 'camera_abc', push: publishConfigOf('final-secret') }) as AqvisionAgencyApiClient['rotateStreamKey'],
    });

    const response = await service.createCameraAqpStreamKey(
      createCameraAqpStreamKeyInput as never,
      opUser,
    );

    // rotate #1: cấp lại key đã thu hồi; PATCH đổi tên; rotate #2: lấy push mới sau rename.
    expect(agencyClient.rotateStreamKey).toHaveBeenCalledTimes(2);
    expect(agencyClient.rotateStreamKey).toHaveBeenNthCalledWith(1, 'free-9');
    expect(agencyClient.updateStreamKey).toHaveBeenCalledWith(
      'free-9',
      { stream: 'camera_abc' },
      'PATCH',
