  private async ensureCameraAqpStreamKey(
    camera: AqpStreamKeyCamera,
    lease: CameraLeaseHandle,
  ): Promise<AqvisionAgencyStreamKey> {
    let existingId = camera.aqpStreamKeyId;
    if (existingId) {
      try {
        const current = await this.aqvisionAgencyApiClient.getStreamKey(existingId);
        this.assertAqpCameraKeyMatches(camera.streamName, current);
        this.assertAqpLeaseOwned(lease);
        if (current.push) return current;
      } catch (error) {
        if (!(error instanceof AqvisionAgencyApiException) || error.httpStatus !== 404) {
          throw this.toAqpServiceUnavailable(error);
        }
        await this.saveAqpStreamKeyId(camera.id, null, lease);
        existingId = null;
      }
    }

    // Camera chưa liên kết (hoặc liên kết vừa bị gỡ): dùng lại key rảnh trong kho
    // trước khi POST tạo key mới — giới hạn 10 key/agency nên mỗi key mất là mất vĩnh viễn.
    if (!existingId) {
      const reused = await this.reuseFreeAqpStreamKey(camera, lease);
      this.assertAqpLeaseOwned(lease);
      if (reused) return reused;
    }

    this.assertAqpLeaseOwned(lease);
    let key: AqvisionAgencyStreamKey;
    try {
      key = await this.aqvisionAgencyApiClient.createStreamKey({
        app: 'live',
        stream: camera.streamName,
      });
    } catch (error) {
      if (
        error instanceof AqvisionAgencyApiException &&
        (error.httpStatus === 409 || error.mayHaveApplied)
      ) {
        key = await this.reconcileAqpStreamKey(camera.streamName);
      } else if (await this.hasReachedAqpStreamKeyLimit()) {
        // Cạn kho: báo BTC rõ nguyên nhân thay vì lỗi AQP chung chung.
        throw new ServiceUnavailableException(
          'Đã dùng hết 10 key AQP. Thu hồi key không giải phóng kho; hãy xoá key trực tiếp ' +
            'trên trang AQP hoặc liên hệ AQP nâng giới hạn, rồi tạo key lại cho camera này.',
        );
      } else {
        throw this.toAqpServiceUnavailable(error);
      }
    }

    this.assertAqpCameraKeyMatches(camera.streamName, key);
    if (!key.push) {
      throw new ServiceUnavailableException('AQP chưa trả cấu hình RTMP cho stream key.');
    }
    await this.saveAqpStreamKeyId(camera.id, key.id, lease);
    return key;
  }

  /**
   * Dùng lại key rảnh trong kho đại lý trước khi POST tạo key mới, dưới lease Redis
   * chung cho toàn bộ kho: hai backend instance không được chọn cùng một key để gắn
   * cho hai camera cùng lúc. Trả `null` khi hết key phù hợp hoặc mất lease kho —
   * caller POST tạo key mới (an toàn: key mới không thể va unique index).
   */
  private async reuseFreeAqpStreamKey(
    camera: AqpStreamKeyCamera,
    lease: CameraLeaseHandle,
  ): Promise<AqvisionAgencyStreamKey | null> {
    return this.livestreamHealthQueue.runWithAqpStreamKeyPoolLock(
      camera.id,
      async (poolLease) => {
        const combined: CameraLeaseHandle = {
          cameraId: camera.id,
          isOwned: () => lease.isOwned() && poolLease.isOwned(),
        };
        return this.pickFreeAqpStreamKey(camera, combined);
      },
    );
  }

  /**
   * Chọn và gắn key rảnh đầu tiên dùng được. Key rảnh = key `live`, tên stream thuộc
   * namespace của môi trường này và KHÔNG camera nào đang gắn (kể cả camera đã xoá
   * mềm — unique index `aqp_stream_key_id` phủ toàn bảng). Trả `null` khi không còn
   * key nào; ném khi lỗi AQP thật (list thất bại) hoặc mất lease.
   */
  private async pickFreeAqpStreamKey(
    camera: AqpStreamKeyCamera,
    lease: CameraLeaseHandle,
  ): Promise<AqvisionAgencyStreamKey | null> {
    let keys: AqvisionAgencyStreamKey[];
    try {
      keys = await this.aqvisionAgencyApiClient.listStreamKeys();
    } catch (error) {
      throw this.toAqpServiceUnavailable(error);
    }
    this.assertAqpLeaseOwned(lease);

    // Chỉ key của CHÍNH namespace môi trường này mới dùng lại được: mọi môi trường
    // mặc định tiền tố `camera_`, nên không thể chỉ lọc theo tiền tố đó.
    const prefix = this.getAqpStreamNamePrefix();
    for (const candidate of keys) {
      if (candidate.app !== 'live' || !candidate.stream.startsWith(prefix)) continue;
      if (await this.livestreamRepository.isAqpStreamKeyIdInUse(candidate.id)) continue;
      const attached = await this.attachAqpStreamKeyFromPool(candidate, camera, lease);
      if (attached) return attached;
    }
    return null;
  }

  /**
   * Gắn một key rảnh cho camera: lấy detail → rotate/POST kích hoạt lại (nếu đã bị
   * thu hồi trước đây) → PATCH đổi tên stream sang tên camera → rotate lấy push mới
   * → gắn DB. Trả `null` khi key này không dùng được để caller thử key kế tiếp;
   * ném khi mất lease hoặc lỗi AQP ngoài dự kiến.
   */
  private async attachAqpStreamKeyFromPool(
    candidate: AqvisionAgencyStreamKey,
    camera: AqpStreamKeyCamera,
    lease: CameraLeaseHandle,
  ): Promise<AqvisionAgencyStreamKey | null> {
    let key: AqvisionAgencyStreamKey;
    try {
      key = await this.aqvisionAgencyApiClient.getStreamKey(candidate.id);
      this.assertAqpLeaseOwned(lease);
    } catch (error) {
      if (error instanceof AqvisionAgencyApiException && error.httpStatus === 404) {
        return null; // Key vừa biến khỏi AQP: thử key rảnh kế tiếp.
      }
      throw this.toAqpServiceUnavailable(error);
    }

    // Key đã bị thu hồi trước đây (`push` null): cấp lại bằng rotate; lỗi thì POST
    // kích hoạt lại chính key đó dưới tên cũ; vẫn lỗi thì bỏ qua key này.
    if (!key.push) {
      key = await this.reactivateRevokedAqpStreamKey(key, lease);
      if (!key) return null;
    }

    if (key.app !== 'live' || key.stream !== camera.streamName) {
      key = await this.renameAqpStreamKeyToCamera(key, camera, lease);
      if (!key) return null;
    }

    // Đổi tên thường trả key ở trạng thái thu hồi (`push` null): rotate để có push
    // mới; lỗi thì POST tạo key dưới tên đích.
    if (!key.push) {
      key = await this.issuePushForAqpStreamKey(key, camera, lease);
      if (!key) return null;
    }

    if (!key.push) return null;
    this.assertAqpCameraKeyMatches(camera.streamName, key);

    try {
      await this.saveAqpStreamKeyId(camera.id, key.id, lease);
    } catch (error) {
      // Camera khác vừa gắn key này (vi phạm unique index toàn bảng): thử key kế tiếp.
      if (!this.isUniqueViolation(error)) throw error;
      return null; // Vi phạm unique index (23505): camera khác vừa gắn key này, thử key kế tiếp.
    }
    return key;
  }

  /** Cấp lại push cho key đã thu hồi: rotate trước, lỗi thì POST kích hoạt lại chính key đó dưới tên cũ. Trả null khi cả hai đều lỗi (bỏ qua key). */
  private async reactivateRevokedAqpStreamKey(
    key: AqvisionAgencyStreamKey,
    lease: CameraLeaseHandle,
  ): Promise<AqvisionAgencyStreamKey | null> {
    try {
      const rotated = await this.aqvisionAgencyApiClient.rotateStreamKey(key.id);
      this.assertAqpLeaseOwned(lease);
      return rotated;
    } catch (error) {
      if (error instanceof ServiceUnavailableException) throw error; // mất lease: dừng ngay
      this.assertAqpLeaseOwned(lease);
      try {
        const reactivated = await this.aqvisionAgencyApiClient.createStreamKey({
          app: 'live',
          stream: key.stream,
        });
        this.assertAqpLeaseOwned(lease);
        return reactivated;
      } catch (reactivateError) {
        if (reactivateError instanceof ServiceUnavailableException) throw reactivateError;
        return null; // rotate và POST kích hoạt lại đều lỗi: bỏ qua key này.
      }
    }
  }

  /** PATCH đổi tên stream key về tên camera. Trả null khi tên bị key khác giữ (409) hoặc rename thất bại không xác định. */
  private async renameAqpStreamKeyToCamera(
    key: AqvisionAgencyStreamKey,
    camera: AqpStreamKeyCamera,
    lease: CameraLeaseHandle,
  ): Promise<AqvisionAgencyStreamKey | null> {
    let renamed: AqvisionAgencyStreamKey;
    try {
      renamed = await this.aqvisionAgencyApiClient.updateStreamKey(
        key.id,
        { stream: camera.streamName },
        'PATCH',
      );
      this.assertAqpLeaseOwned(lease);
    } catch (error) {
      if (error instanceof ServiceUnavailableException) throw error;
      if (!(error instanceof AqvisionAgencyApiException)) throw error;
      if (error.httpStatus === 409) {
        return null; // Tên stream đích đang bị key khác giữ: thử key rảnh kế tiếp.
      }
      if (!error.mayHaveApplied) {
        throw this.toAqpServiceUnavailable(error);
      }
      // Không chắc PATCH đã thành hay chưa: đọc lại và chỉ tiếp tục khi tên đã đúng đích.
      try {
        renamed = await this.aqvisionAgencyApiClient.getStreamKey(key.id);
        this.assertAqpLeaseOwned(lease);
      } catch (reconcileError) {
        throw this.toAqpServiceUnavailable(reconcileError);
      }
    }
    return renamed.app === 'live' && renamed.stream === camera.streamName ? renamed : null;
  }

  /** Rotate để lấy push mới cho key (sau đổi tên thường rơi về `push` null); lỗi thì POST tạo dưới tên đích. Trả null khi cả hai đều lỗi. */
  private async issuePushForAqpStreamKey(
    key: AqvisionAgencyStreamKey,
    camera: AqpStreamKeyCamera,
