import {
  BadRequestException,
  ConflictException,
  ForbiddenException,
  ServiceUnavailableException,
} from '@nestjs/common';
import type { ConfigService } from '@nestjs/config';
import type { AqvisionAgencyApiClient, AqvisionAgencyStreamKey } from './aqvision-agency-api.client';
import { AqvisionAgencyApiException } from './aqvision-agency-api.client';
import { AqvisionApiClient } from './aqvision-api.client';
import { AqvisionPublishService } from './aqvision-publish.service';
import type { JwtPayload } from '../auth/interfaces/jwt-payload.interface';
import type { LivestreamRepository } from './livestream.repository';
import type { AqvisionRecordingService } from './aqvision-recording.service';
import type { LivestreamHealthQueue } from './livestream-health.queue';
import type { LivestreamCameraSourceCryptoService } from './livestream-camera-source-crypto.service';
import { LivestreamService, type AqpCameraStreamKeyResponse } from './livestream.service';

const owner: JwtPayload = {
  sub: 'owner-1',
  email: 'owner@example.com',
  role: 'USER',
  roles: [],
};
const stranger: JwtPayload = {
  sub: 'other-1',
  email: 'other@example.com',
  role: 'USER',
  roles: [],
};
const tournamentId = '11111111-1111-4111-8111-111111111111';
const camera = {
  id: 'camera-1',
  tournamentId,
  courtId: null,
  name: 'Camera sân 1',
  mode: 'PUSH',
  protocol: 'RTMP',
  streamName: 'camera_abc',
  streamKey: 'internal-secret-must-not-leak',
  aqpStreamKeyId: null as string | null,
  status: 'IDLE',
  playbackUrl: 'https://media.aqvision.net/live/camera_abc/hls.m3u8',
  createdAt: new Date('2026-10-01T00:00:00.000Z'),
  updatedAt: new Date('2026-10-01T00:00:00.000Z'),
};
const activeKey: AqvisionAgencyStreamKey = {
  id: 'aqp-key-1',
  app: 'live',
  stream: 'camera_abc',
  status: 'Offline',
  push: {
    rtmpServer: 'rtmp://push.aqvision.net:11935/live',
    streamKey: 'camera_abc?key=provider-secret',
  },
};
const defaultPushConfig: Record<string, string> = {
  AQVISION_PUSH_HOST: 'media.aqvision.net',
  AQVISION_PUSH_PORT: '18554',
};

function makeService(options: {
  camera?: typeof camera;
  staff?: boolean;
  lockResult?: boolean;
  agency?: Partial<Record<keyof AqvisionAgencyApiClient, jest.Mock>>;
  pushConfig?: Record<string, string>;
  isMediaOnline?: jest.Mock;
  inUseKeys?: string[];
} = {}) {
  const currentCamera = options.camera ?? camera;
  const repository = {
    findCameraById: jest.fn().mockResolvedValue(currentCamera),
    findTournamentById: jest
      .fn()
      .mockResolvedValue({ id: tournamentId, name: 'Giải', createdBy: owner.sub }),
    isTournamentStaff: jest.fn().mockResolvedValue(options.staff ?? false),
    setAqpStreamKeyId: jest.fn().mockResolvedValue(true),
    hasCameraRecordings: jest.fn().mockResolvedValue(false),
    isCameraStreamNameTaken: jest.fn().mockResolvedValue(false),
    updateCameraStreamName: jest.fn().mockResolvedValue({
      ...currentCamera,
      streamName: 'camera_new',
      playbackUrl: 'https://media.aqvision.net/live/camera_new/hls.m3u8',
    }),
    deleteCamera: jest.fn().mockResolvedValue(currentCamera),
    // Pool: key rảnh trừ khi có camera nào (kể cả ARCHIVED) đang gắn — unique index phủ toàn bảng.
    isAqpStreamKeyIdInUse: jest.fn().mockImplementation(async (aqpStreamKeyId: string) =>
      Boolean((options.inUseKeys ?? []).includes(aqpStreamKeyId)),
    ),
  };
  const agencyClient = {
    createStreamKey: jest.fn().mockResolvedValue(activeKey),
    listStreamKeys: jest.fn().mockResolvedValue([]),
    getStreamKey: jest.fn().mockResolvedValue(activeKey),
    updateStreamKey: jest.fn().mockResolvedValue({
      ...activeKey,
      stream: 'camera_new',
      push: null,
    }),
    rotateStreamKey: jest.fn().mockResolvedValue(activeKey),
    ...options.agency,
  };
  const lock = {
    isOwned: jest.fn().mockReturnValue(options.lockResult ?? true),
  };
  const healthQueue = {
    runWithCameraLock: jest.fn(async (_cameraId: string, operation: (lease: typeof lock) => Promise<unknown>) =>
      options.lockResult === false ? null : operation(lock),
    ),
    runWithStreamNameLock: jest.fn(async (_cameraId: string, _streamName: string, operation: (lease: typeof lock) => Promise<unknown>) =>
      options.lockResult === false ? null : operation(lock),
    ),
    // Lease chung cho kho key: test chạy đơn instance nên luôn đi thẳng vào operation.
    runWithAqpStreamKeyPoolLock: jest.fn(async (_cameraId: string, operation: (lease: typeof lock) => Promise<unknown>) =>
      operation(lock),
    ),
  };
  const configService = {
    get: jest.fn(
      (key: string, fallback?: unknown) => (options.pushConfig ?? defaultPushConfig)[key] ?? fallback,
    ),
  } as unknown as ConfigService;
  const aqvisionApiClient = {
    isMediaOnline: options.isMediaOnline ?? jest.fn().mockResolvedValue({ online: false }),
  };
  const service = new LivestreamService(
    repository as unknown as LivestreamRepository,
    configService,
    new AqvisionPublishService(configService),
    aqvisionApiClient as unknown as AqvisionApiClient,
    {} as unknown as AqvisionRecordingService,
    healthQueue as unknown as LivestreamHealthQueue,
    {} as LivestreamCameraSourceCryptoService,
    agencyClient as unknown as AqvisionAgencyApiClient,
  );
  return {
    service,
    repository,
    agencyClient,
    healthQueue,
    lock,
    aqvisionApiClient,
    readResult: (streamKeyId: string | null, key: AqvisionAgencyStreamKey | null): AqpCameraStreamKeyResponse =>
      service.toAqpCameraStreamKeyResponseForTest(currentCamera, key, streamKeyId),
  };
}

describe('LivestreamService AQP stream-key lifecycle', () => {
  it('creates a provider key, stores only its ID, and returns the RTSP QR plus the RTMP OBS fields from data.push', async () => {
    const { service, repository, agencyClient } = makeService();

    const result = await service.createCameraAqpStreamKey('camera-1', owner);

    // Luôn đọc kho trước (listStreamKeys) rồi mới POST — kho rỗng nên POST tạo mới.
    expect(agencyClient.listStreamKeys).toHaveBeenCalledTimes(1);
    expect(agencyClient.createStreamKey).toHaveBeenCalledWith({ app: 'live', stream: 'camera_abc' });
    expect(repository.setAqpStreamKeyId).toHaveBeenCalledWith('camera-1', activeKey.id);
    expect(result.rtmp).toEqual({
      server: activeKey.push?.rtmpServer,
      streamKey: activeKey.push?.streamKey,
    });
    expect(result.qrPayload).toEqual({
      stream_url: 'rtsp://media.aqvision.net:18554/live/camera_abc?key=provider-secret',
      match_id: 'camera_abc',
      match_title: 'Camera sân 1',
      protocol: 'rtsp',
      auto_start: false,
    });
    expect(JSON.stringify(result)).not.toContain('internal-secret-must-not-leak');
  });

  it('fails closed with the env names when the RTSP push endpoint is not configured', async () => {
    const { service } = makeService({ pushConfig: {} });

    await expect(service.createCameraAqpStreamKey('camera-1', owner)).rejects.toThrow(
      /AQVISION_PUSH_HOST/,
    );
  });

  it('refuses to build a QR when the provider stream key carries no publish key', async () => {
    const { service } = makeService({
      agency: {
        createStreamKey: jest.fn().mockResolvedValue({
          ...activeKey,
          push: { rtmpServer: 'rtmp://push.aqvision.net:11935/live', streamKey: 'camera_abc' },
        }),
      },
    });

    await expect(service.createCameraAqpStreamKey('camera-1', owner)).rejects.toThrow(
      ServiceUnavailableException,
    );
  });
  it('reuses the exact provider stream found by the preflight list before POST', async () => {
    const { service, repository, agencyClient } = makeService({
      agency: {
        listStreamKeys: jest.fn().mockResolvedValue([
          {
            id: activeKey.id,
            app: activeKey.app,
            stream: activeKey.stream,
            status: activeKey.status,
            push: null,
          },
        ]),
        getStreamKey: jest.fn().mockResolvedValue(activeKey),
      },
    });

    const result = await service.createCameraAqpStreamKey('camera-1', owner);

    expect(agencyClient.listStreamKeys).toHaveBeenCalledTimes(1);
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
    // Key rảnh đúng tên + có push: gắn thẳng, không rename, không rotate (rotate chỉ khi đổi chủ).
    expect(agencyClient.updateStreamKey).not.toHaveBeenCalled();
    expect(agencyClient.rotateStreamKey).not.toHaveBeenCalled();
    expect(repository.setAqpStreamKeyId).toHaveBeenCalledWith('camera-1', activeKey.id);
    expect(result.streamKeyId).toBe(activeKey.id);
  });

  it('does not POST when the provider preflight list cannot be read', async () => {
    const { service, agencyClient } = makeService({
      agency: {
        listStreamKeys: jest
          .fn()
          .mockRejectedValue(new AqvisionAgencyApiException('unavailable', 503)),
      },
    });

    await expect(service.createCameraAqpStreamKey('camera-1', owner)).rejects.toBeInstanceOf(
      ServiceUnavailableException,
    );
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
  });

  it('reconciles a timed-out POST through list/detail without issuing a duplicate POST', async () => {
    const providerError = new AqvisionAgencyApiException('timeout', null, true);
    const { service, repository, agencyClient } = makeService({
      agency: {
        createStreamKey: jest.fn().mockRejectedValue(providerError),
        listStreamKeys: jest
          .fn()
          .mockResolvedValueOnce([])
          .mockResolvedValueOnce([
            { id: activeKey.id, app: activeKey.app, stream: activeKey.stream, status: activeKey.status, push: null },
          ]),
        getStreamKey: jest.fn().mockResolvedValue(activeKey),
      },
    });

    const result = await service.createCameraAqpStreamKey('camera-1', owner);

    expect(agencyClient.createStreamKey).toHaveBeenCalledTimes(1);
    expect(agencyClient.getStreamKey).toHaveBeenCalledWith(activeKey.id);
    expect(repository.setAqpStreamKeyId).toHaveBeenCalledWith('camera-1', activeKey.id);
    expect(result.streamKeyId).toBe(activeKey.id);
  });

  it('reads a linked key without creating another provider key', async () => {
    const linkedCamera = { ...camera, aqpStreamKeyId: activeKey.id };
    const { service, agencyClient } = makeService({ camera: linkedCamera });

    const result = await service.getCameraAqpStreamKey('camera-1', owner);

    expect(agencyClient.getStreamKey).toHaveBeenCalledWith(activeKey.id);
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
    expect(result.status).toBe('Offline');
  });
  it('clears a stale local link when the provider no longer has the key', async () => {
    const linkedCamera = { ...camera, aqpStreamKeyId: activeKey.id };
    const { service, repository, agencyClient } = makeService({
      camera: linkedCamera,
      agency: {
        getStreamKey: jest.fn().mockRejectedValue(new AqvisionAgencyApiException('missing', 404)),
      },
    });

    const result = await service.getCameraAqpStreamKey('camera-1', owner);

    expect(result.streamKeyId).toBeNull();
    expect(repository.setAqpStreamKeyId).toHaveBeenCalledWith('camera-1', null);
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
  });

  it('reuses a free pool key instead of creating a new one (rename → rotate → attach)', async () => {
    const freeKey: AqvisionAgencyStreamKey = {
      id: 'free-1',
      app: 'live',
      stream: 'camera_free_1',
      status: 'Offline',
      push: { rtmpServer: 'rtmp://push.aqvision.net:11935/live', streamKey: 'free?key=old-secret' },
    };
    const rotatedAfterRename: AqvisionAgencyStreamKey = {
      ...freeKey,
      stream: 'camera_abc',
      push: { rtmpServer: 'rtmp://push.aqvision.net:11935/live', streamKey: 'camera_abc?key=pool-secret' },
    };
    const { service, repository, agencyClient } = makeService({
      agency: {
        listStreamKeys: jest.fn().mockResolvedValue([freeKey]),
        getStreamKey: jest.fn().mockResolvedValue(freeKey),
        updateStreamKey: jest.fn().mockResolvedValue({ ...freeKey, stream: 'camera_abc', push: null }),
        rotateStreamKey: jest.fn().mockResolvedValue(rotatedAfterRename),
      },
    });

    const result = await service.createCameraAqpStreamKey('camera-1', owner);

    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
    expect(agencyClient.updateStreamKey).toHaveBeenCalledWith(
      'free-1',
      { stream: 'camera_abc' },
      'PATCH',
    );
    expect(agencyClient.rotateStreamKey).toHaveBeenCalledWith('free-1');
    expect(repository.setAqpStreamKeyId).toHaveBeenCalledWith('camera-1', 'free-1');
    expect(result.streamKeyId).toBe('free-1');
    expect(result.rtmp).toEqual({
      server: rotatedAfterRename.push?.rtmpServer,
      streamKey: rotatedAfterRename.push?.streamKey,
    });
  });

  it('skips a pool key another camera holds, including soft-deleted and archived cameras', async () => {
    const heldKey: AqvisionAgencyStreamKey = {
      id: 'used-1',
      app: 'live',
      stream: 'camera_used_1',
      status: 'Offline',
      push: null,
    };
    const freeKey: AqvisionAgencyStreamKey = {
      id: 'free-2',
      app: 'live',
      stream: 'camera_free_2',
      status: 'Offline',
      push: { rtmpServer: 'rtmp://push.aqvision.net:11935/live', streamKey: 'free2?key=secret' },
    };
    const { agencyClient, repository } = makeService({
      inUseKeys: ['used-1'],
      agency: {
        listStreamKeys: jest.fn().mockResolvedValue([heldKey, freeKey]),
        getStreamKey: jest.fn().mockResolvedValue(freeKey),
      },
    });

    await service.createCameraAqpStreamKey('camera-1', owner);

    // Unique index `aqp_stream_key_id` phủ toàn bảng: key đang gắn (kể cả ARCHIVED) không rảnh.
    expect(repository.isAqpStreamKeyIdInUse).toHaveBeenCalledWith('used-1');
    expect(repository.isAqpStreamKeyIdInUse).toHaveBeenCalledWith('free-2');
    expect(agencyClient.getStreamKey).toHaveBeenCalledTimes(1);
    expect(agencyClient.getStreamKey).toHaveBeenCalledWith('free-2');
    expect(agencyClient.updateStreamKey).not.toHaveBeenCalled();
    expect(agencyClient.rotateStreamKey).not.toHaveBeenCalled();
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
  });

  it('only reuses pool keys inside this environment stream-name namespace', async () => {
    const foreignKey: AqvisionAgencyStreamKey = {
      id: 'legacy-1',
      app: 'live',
      // Đúng tiền tố mặc định `camera_` nhưng KHÔNG thuộc namespace `prod_camera_` của môi trường này.
      stream: 'camera_legacy_1',
      status: 'Offline',
      push: { rtmpServer: 'rtmp://push.aqvision.net:11935/live', streamKey: 'legacy?key=secret' },
    };
    const ownKey: AqvisionAgencyStreamKey = {
      id: 'prod-1',
      app: 'live',
      stream: 'prod_camera_free_1',
      status: 'Offline',
      push: { rtmpServer: 'rtmp://push.aqvision.net:11935/live', streamKey: 'prod?key=secret' },
    };
    const { service, agencyClient } = makeService({
      pushConfig: {
        ...defaultPushConfig,
        AQVISION_STREAM_NAME_PREFIX: 'prod_camera_',
      },
      // Camera ở namespace `prod_camera_` (tên tự tạo theo prefix env).
      camera: { ...camera, streamName: 'prod_camera_abc' },
      agency: {
        listStreamKeys: jest.fn().mockResolvedValue([foreignKey, ownKey]),
        getStreamKey: jest.fn().mockResolvedValue(ownKey),
        updateStreamKey: jest.fn().mockResolvedValue({ ...ownKey, stream: 'prod_camera_abc', push: null }),
        rotateStreamKey: jest.fn().mockResolvedValue({
          ...ownKey,
          stream: 'prod_camera_abc',
          push: { rtmpServer: 'rtmp://push.aqvision.net:11935/live', streamKey: 'prod?key=new' },
        }),
      },
    });

    await service.createCameraAqpStreamKey('camera-1', owner);

    // Key ngoài namespace: không GET detail, không gắn, không POST kích hoạt lại.
    expect(agencyClient.getStreamKey).toHaveBeenCalledTimes(1);
    expect(agencyClient.getStreamKey).toHaveBeenCalledWith('prod-1');
    expect(agencyClient.updateStreamKey).toHaveBeenCalledWith(
      'prod-1',
      { stream: 'prod_camera_abc' },
      'PATCH',
    );
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
  });

  it('reactivates a revoked pool key by rotate, then renames and rotates again', async () => {
    const revokedKey: AqvisionAgencyStreamKey = {
      id: 'free-9',
      app: 'live',
      stream: 'camera_old_9',
      status: 'Offline',
      push: null,
    };
    const afterFirstRotate: AqvisionAgencyStreamKey = {
      ...revokedKey,
      stream: 'camera_old_9',
      push: { rtmpServer: 'rtmp://push.aqvision.net:11935/live', streamKey: 'old9?key=revived' },
    };
    const afterRenameRotate: AqvisionAgencyStreamKey = {
      ...revokedKey,
      stream: 'camera_abc',
      push: { rtmpServer: 'rtmp://push.aqvision.net:11935/live', streamKey: 'old9?key=final' },
    };
    const { service, repository, agencyClient } = makeService({
      agency: {
        listStreamKeys: jest.fn().mockResolvedValue([revokedKey]),
        getStreamKey: jest.fn().mockResolvedValue(revokedKey),
        rotateStreamKey: jest
          .fn()
          .mockResolvedValueOnce(afterFirstRotate)
          .mockResolvedValueOnce(afterRenameRotate),
        updateStreamKey: jest.fn().mockResolvedValue({ ...revokedKey, stream: 'camera_abc', push: null }),
      },
    });

    const result = await service.createCameraAqpStreamKey('camera-1', owner);

    // rotate #1 cấp lại key đã thu hồi (không POST), PATCH đổi tên, rotate #2 lấy push mới.
    expect(agencyClient.rotateStreamKey).toHaveBeenCalledTimes(2);
    expect(agencyClient.rotateStreamKey).toHaveBeenNthCalledWith(1, 'free-9');
    expect(agencyClient.rotateStreamKey).toHaveBeenNthCalledWith(2, 'free-9');
    expect(agencyClient.updateStreamKey).toHaveBeenCalledWith(
      'free-9',
      { stream: 'camera_abc' },
      'PATCH',
    );
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
    expect(repository.setAqpStreamKeyId).toHaveBeenCalledWith('camera-1', 'free-9');
    expect(result.streamKeyId).toBe('free-9');
    expect(result.rtmp?.streamKey).toBe('old9?key=final');
  });

  it('reactivates a revoked pool key by re-POSTing the same key under its old name when rotate fails', async () => {
    const revokedKey: AqvisionAgencyStreamKey = {
      id: 'free-9',
      app: 'live',
      stream: 'camera_old_9',
      status: 'Offline',
      push: null,
    };
    const reactivated: AqvisionAgencyStreamKey = {
      ...revokedKey,
      push: { rtmpServer: 'rtmp://push.aqvision.net:11935/live', streamKey: 'old9?key=revived' },
    };
    const { service, agencyClient } = makeService({
      agency: {
        listStreamKeys: jest.fn().mockResolvedValue([revokedKey]),
        getStreamKey: jest.fn().mockResolvedValue(revokedKey),
        rotateStreamKey: jest
          .fn()
          .mockRejectedValueOnce(new AqvisionAgencyApiException('revoked', 500))
          .mockResolvedValue({
            ...revokedKey,
            stream: 'camera_abc',
            push: { rtmpServer: 'rtmp://push.aqvision.net:11935/live', streamKey: 'old9?key=final' },
          }),
        updateStreamKey: jest.fn().mockResolvedValue({ ...revokedKey, stream: 'camera_abc', push: null }),
        createStreamKey: jest.fn().mockResolvedValue(reactivated),
      },
    });

    const result = await service.createCameraAqpStreamKey('camera-1', owner);

    // POST kích hoạt lại CHÍNH key đó dưới tên cũ (không tạo key mới), rồi rename + rotate.
    expect(agencyClient.createStreamKey).toHaveBeenCalledTimes(1);
    expect(agencyClient.createStreamKey).toHaveBeenCalledWith({
      app: 'live',
      stream: 'camera_old_9',
    });
    expect(agencyClient.updateStreamKey).toHaveBeenCalledWith(
      'free-9',
      { stream: 'camera_abc' },
      'PATCH',
    );
    expect(result.streamKeyId).toBe('free-9');
    expect(result.rtmp?.streamKey).toContain('old9?key=final');
  });

  it('skips a revoked pool key when both rotate and reactivation POST fail', async () => {
    const revokedKey: AqvisionAgencyStreamKey = {
      id: 'free-9',
      app: 'live',
      stream: 'camera_old_9',
      status: 'Offline',
      push: null,
    };
    const { service, repository, agencyClient } = makeService({
      agency: {
        listStreamKeys: jest.fn().mockResolvedValue([revokedKey]),
        getStreamKey: jest.fn().mockResolvedValue(revokedKey),
        rotateStreamKey: jest
          .fn()
          .mockRejectedValue(new AqvisionAgencyApiException('revoked', 500)),
        createStreamKey: jest
          .fn()
          .mockRejectedValueOnce(new AqvisionAgencyApiException('cannot reactivate', 500))
          .mockResolvedValueOnce(activeKey),
      },
    });

    const result = await service.createCameraAqpStreamKey('camera-1', owner);

    // POST kích hoạt lại lỗi → bỏ qua key này → tạo key mới чисто cho camera.
    expect(agencyClient.createStreamKey).toHaveBeenCalledTimes(2);
    expect(agencyClient.createStreamKey).toHaveBeenNthCalledWith(1, {
      app: 'live',
      stream: 'camera_old_9',
    });
    expect(agencyClient.createStreamKey).toHaveBeenNthCalledWith(2, {
      app: 'live',
      stream: 'camera_abc',
    });
    expect(repository.setAqpStreamKeyId).toHaveBeenCalledWith('camera-1', activeKey.id);
    expect(result.streamKeyId).toBe(activeKey.id);
  });

  it('tries the next free key when attaching races another camera on the unique index', async () => {
    const freeOne: AqvisionAgencyStreamKey = {
      id: 'free-1',
      app: 'live',
      stream: 'camera_free_1',
      status: 'Offline',
      push: { rtmpServer: 'rtmp://push.aqvision.net:11935/live', streamKey: 'one?key=old' },
    };
    const freeTwo: AqvisionAgencyStreamKey = {
      id: 'free-2',
      app: 'live',
      stream: 'camera_free_2',
      status: 'Offline',
      push: { rtmpServer: 'rtmp://push.aqvision.net:11935/live', streamKey: 'two?key=old' },
    };
    const { service, repository, agencyClient } = makeService({
      agency: {
        listStreamKeys: jest.fn().mockResolvedValue([freeOne, freeTwo]),
        getStreamKey: jest
          .fn()
          .mockResolvedValueOnce(freeOne)
          .mockResolvedValueOnce(freeTwo),
        updateStreamKey: jest
          .fn()
          .mockResolvedValueOnce({ ...freeOne, stream: 'camera_abc', push: null })
          .mockResolvedValueOnce({ ...freeTwo, stream: 'camera_abc', push: null }),
        rotateStreamKey: jest
          .fn()
          .mockResolvedValueOnce({
            ...freeOne,
            stream: 'camera_abc',
            push: { rtmpServer: 'rtmp://push.aqvision.net:11935/live', streamKey: 'one?key=new' },
          })
          .mockResolvedValueOnce({
            ...freeTwo,
            stream: 'camera_abc',
            push: { rtmpServer: 'rtmp://push.aqvision.net:11935/live', streamKey: 'two?key=new' },
          }),
      },
      // Camera khác vừa gắn free-1 sau khi kho đọc xong (vi phạm unique index toàn bảng).
    });
    (repository.setAqpStreamKeyId as jest.Mock)
      .mockRejectedValueOnce({ code: '23505' })
      .mockResolvedValue(true);

    const result = await service.createCameraAqpStreamKey('camera-1', owner);

    // Va unique index (23505) từ saveAqpStreamKeyId: retry key rảnh kế tiếp, không lỗi cho BTC.
    expect(repository.setAqpStreamKeyId).toHaveBeenNthCalledWith(1, 'camera-1', 'free-1');
    expect(repository.setAqpStreamKeyId).toHaveBeenNthCalledWith(2, 'camera-1', 'free-2');
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
    expect(agencyClient.rotateStreamKey).toHaveBeenCalledWith('free-1');
    expect(agencyClient.rotateStreamKey).toHaveBeenCalledWith('free-2');
    expect(result.streamKeyId).toBe('free-2');
    expect(result.rtmp?.streamKey).toBe('two?key=new');
  });

  it('reports the exhausted 10-key pool distinctly when creating a new key fails', async () => {
    const tenKeys: AqvisionAgencyStreamKey[] = Array.from({ length: 10 }, (_, index) => ({
      id: `pool-key-${index}`,
      app: 'live',
      stream: `camera_pool_${index}`,
      status: 'Offline',
      push: null,
    }));
    const { service, agencyClient } = makeService({
      agency: {
        // Kho rỗng ở lượt chọn key…
        listStreamKeys: jest
          .fn()
          .mockResolvedValueOnce([])
          // …nhưng đếm thời gian thực khi POST lỗi: đã đủ 10 key (kể cả key đã thu hồi).
          .mockResolvedValueOnce(tenKeys),
        createStreamKey: jest
          .fn()
          .mockRejectedValue(new AqvisionAgencyApiException('create failed', 500)),
      },
    });

    await expect(service.createCameraAqpStreamKey('camera-1', owner)).rejects.toThrow(
      'Đã dùng hết 10 key AQP',
    );
    expect(agencyClient.listStreamKeys).toHaveBeenCalledTimes(2);
    // Thu hồi key không giải phóng kho: BTC phải xử lý kho trên trang AQP, không retry mù.
    expect(agencyClient.createStreamKey).toHaveBeenCalledTimes(1);
  });

  it('keeps the original AQP error when the pool has fewer than 10 keys', async () => {
    const { service, agencyClient } = makeService({
      agency: {
        listStreamKeys: jest
          .fn()
          .mockResolvedValueOnce([])
          .mockResolvedValueOnce([
            { id: 'one', app: 'live', stream: 'camera_one', status: 'Offline', push: null },
            { id: 'two', app: 'live', stream: 'camera_two', status: 'Offline', push: null },
            { id: 'three', app: 'live', stream: 'camera_three', status: 'Offline', push: null },
          ]),
        createStreamKey: jest
          .fn()
          .mockRejectedValue(new AqvisionAgencyApiException('create failed', 500)),
      },
    });

    await expect(service.createCameraAqpStreamKey('camera-1', owner)).rejects.toThrow('create failed');
    expect(agencyClient.createStreamKey).toHaveBeenCalledTimes(1);
  });

  it('keeps the original AQP error when the pool cannot be counted', async () => {
    const { service, agencyClient } = makeService({
      agency: {
        listStreamKeys: jest
          .fn()
          .mockResolvedValueOnce([])
          .mockRejectedValueOnce(new AqvisionAgencyApiException('list down', 503)),
        createStreamKey: jest
          .fn()
          .mockRejectedValue(new AqvisionAgencyApiException('create failed', 500)),
      },
    });

    await expect(service.createCameraAqpStreamKey('camera-1', owner)).rejects.toThrow('create failed');
    expect(agencyClient.listStreamKeys).toHaveBeenCalledTimes(2);
  });

  it('rotates, renames, save, then rotates again for fresh push instead of deleting and reissuing the provider key', async () => {
    const linkedCamera = { ...camera, aqpStreamKeyId: activeKey.id };
    const { service, repository, agencyClient } = makeService({ camera: linkedCamera });
    const order: string[] = [];
    const renamedFirst: AqvisionAgencyStreamKey = {
      ...activeKey,
      stream: 'camera_new',
      push: null,
    };
    const renamedActiveKey: AqvisionAgencyStreamKey = {
      ...activeKey,
      stream: 'camera_new',
      push: { rtmpServer: 'rtmp://push.example/live', streamKey: 'camera_new?key=new-secret' },
    };
    agencyClient.rotateStreamKey = jest
      .fn()
      .mockResolvedValueOnce(activeKey)
      .mockResolvedValueOnce(renamedActiveKey);
    agencyClient.updateStreamKey = jest.fn(async () => {
      order.push('rename');
      return renamedFirst;
    });
    agencyClient.getStreamKey = jest.fn().mockResolvedValue(activeKey);
    repository.updateCameraStreamName = jest.fn(async () => {
      order.push('save');
      return { ...linkedCamera, streamName: 'camera_new' };
    });
    const originalRotate = agencyClient.rotateStreamKey;
    const trackedRotate = jest.fn(async (keyId: string) => {
      order.push('rotate');
      return originalRotate(keyId);
    });
    agencyClient.rotateStreamKey = trackedRotate;

    const result = await service.renameCameraAqpStreamKey('camera-1', owner, 'camera_new');

    expect(order).toEqual(['rotate', 'rename', 'save', 'rotate']);
    expect(agencyClient.updateStreamKey).toHaveBeenCalledWith(
      activeKey.id,
      { stream: 'camera_new' },
      'PATCH',
    );
    // KHÔNG xoá key (giới hạn 10 key/agency): chính key cũ đổi tên rồi rotate lấy push mới.
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
    expect(result.camera.streamName).toBe('camera_new');
    expect(result.streamKeyId).toBe(activeKey.id);
    expect(result.rtmp?.streamKey).toBe('camera_new?key=new-secret');
  });

  it('reconciles a possibly applied rename before saving the local stream name', async () => {
    const linkedCamera = { ...camera, aqpStreamKeyId: activeKey.id };
    const { service, repository, agencyClient } = makeService({ camera: linkedCamera });
    const renamedRevokedKey: AqvisionAgencyStreamKey = { ...activeKey, stream: 'camera_new', push: null };
    const renamedActiveKey: AqvisionAgencyStreamKey = {
      ...activeKey,
      stream: 'camera_new',
      push: { rtmpServer: 'rtmp://push.example/live', streamKey: 'camera_new?key=rotated' },
    };
    agencyClient.rotateStreamKey = jest
      .fn()
      .mockResolvedValueOnce(activeKey)
      .mockResolvedValueOnce(renamedActiveKey);
    agencyClient.updateStreamKey = jest
      .fn()
      .mockRejectedValue(new AqvisionAgencyApiException('unknown update outcome', null, true));
    agencyClient.getStreamKey = jest
      .fn()
      .mockResolvedValueOnce(activeKey)
      .mockResolvedValue(renamedRevokedKey);
    repository.updateCameraStreamName = jest.fn().mockResolvedValue({
      ...linkedCamera,
      streamName: 'camera_new',
    });

    const result = await service.renameCameraAqpStreamKey('camera-1', owner, 'camera_new');

    // GET #1 đọc linked key, GET #2 hoà giải rename mù — rotate sau rename lấy push mới.
    expect(agencyClient.getStreamKey).toHaveBeenCalledTimes(2);
    expect(repository.updateCameraStreamName).toHaveBeenCalledWith(
      'camera-1',
      'camera_new',
      expect.any(String),
    );
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
    expect(result.camera.streamName).toBe('camera_new');
    expect(result.rtmp?.streamKey).toBe('camera_new?key=rotated');
  });

  it('rejects a stream rename when the camera has a recording', async () => {
    const { service, repository, agencyClient } = makeService({
      camera: { ...camera, aqpStreamKeyId: activeKey.id },
    });
    repository.hasCameraRecordings = jest.fn().mockResolvedValue(true);

    await expect(
      service.renameCameraAqpStreamKey('camera-1', owner, 'camera_new'),
    ).rejects.toBeInstanceOf(ConflictException);
    expect(agencyClient.rotateStreamKey).not.toHaveBeenCalled();
    expect(agencyClient.updateStreamKey).not.toHaveBeenCalled();
  });

  it('rejects rename while another camera holds the target-name lease', async () => {
    const { service, healthQueue, agencyClient } = makeService();
    healthQueue.runWithStreamNameLock.mockResolvedValue(null);

    await expect(
      service.renameCameraAqpStreamKey('camera-1', owner, 'camera_new'),
    ).rejects.toBeInstanceOf(ServiceUnavailableException);

    expect(healthQueue.runWithStreamNameLock).toHaveBeenCalledWith(
      'camera-1',
      'camera_new',
      expect.any(Function),
    );
    expect(agencyClient.rotateStreamKey).not.toHaveBeenCalled();
    expect(agencyClient.updateStreamKey).not.toHaveBeenCalled();
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
  });

  it('rejects a stream name already assigned to another camera before provider calls', async () => {
    const { service, repository, agencyClient } = makeService();
    repository.isCameraStreamNameTaken = jest.fn().mockResolvedValue(true);

    await expect(
      service.renameCameraAqpStreamKey('camera-1', owner, 'camera_new'),
    ).rejects.toBeInstanceOf(ConflictException);
    expect(agencyClient.updateStreamKey).not.toHaveBeenCalled();
  });

  it('rotates the provider key and exposes the newly returned RTMP config', async () => {
    const linkedCamera = { ...camera, aqpStreamKeyId: activeKey.id };
    const rotated: AqvisionAgencyStreamKey = {
      ...activeKey,
      push: { rtmpServer: 'rtmp://push2.aqvision.net/live', streamKey: 'camera_abc?key=new-secret' },
    };
    const { service, agencyClient } = makeService({
      camera: linkedCamera,
      agency: { rotateStreamKey: jest.fn().mockResolvedValue(rotated) },
    });

    const result = await service.rotateCameraAqpStreamKey('camera-1', owner);

    expect(agencyClient.rotateStreamKey).toHaveBeenCalledWith(activeKey.id);
    expect(result.rtmp).toEqual({ server: rotated.push?.rtmpServer, streamKey: rotated.push?.streamKey });
    expect(result.qrPayload?.stream_url).toContain('key=new-secret');
  });

  it('revoking keeps the provider key for reuse: rotates it instead of deleting it', async () => {
    const linkedCamera = { ...camera, aqpStreamKeyId: activeKey.id };
    const rotated: AqvisionAgencyStreamKey = { ...activeKey, push: { ...activeKey.push, streamKey: 'new-secret' } };
    const { service, repository, agencyClient } = makeService({
      camera: linkedCamera,
      agency: { rotateStreamKey: jest.fn().mockResolvedValue(rotated) },
    });

    await expect(service.revokeCameraAqpStreamKey('camera-1', owner)).resolves.toEqual({
      cameraId: 'camera-1',
      keyRevoked: true,
      keptForReuse: true,
    });

    expect(agencyClient.rotateStreamKey).toHaveBeenCalledWith(activeKey.id);
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
    expect(repository.setAqpStreamKeyId).not.toHaveBeenCalledWith('camera-1', null);
  });

  it('revoking a key AQP no longer has unlinks it without creating a new one', async () => {
    const linkedCamera = { ...camera, aqpStreamKeyId: activeKey.id };
    const { service, repository, agencyClient } = makeService({
      camera: linkedCamera,
      agency: {
        rotateStreamKey: jest.fn().mockRejectedValue(new AqvisionAgencyApiException('gone', 404)),
      },
    });

    await expect(service.revokeCameraAqpStreamKey('camera-1', owner)).resolves.toEqual({
      cameraId: 'camera-1',
      keyRevoked: true,
      keptForReuse: false,
    });
    expect(repository.setAqpStreamKeyId).toHaveBeenCalledWith('camera-1', null);
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
  });
  it('rotates the provider key and unlinks it locally before archiving the camera', async () => {
    const linkedCamera = { ...camera, aqpStreamKeyId: activeKey.id };
    const { service, repository, agencyClient } = makeService({ camera: linkedCamera });
    const order: string[] = [];
    agencyClient.rotateStreamKey = jest.fn(async () => {
      order.push('rotate');
      return activeKey;
    });
    (repository.setAqpStreamKeyId as jest.Mock).mockImplementation(async () => {
      order.push('unlink');
      return true;
    });
    repository.deleteCamera.mockImplementation(async () => {
      order.push('archive');
      return linkedCamera;
    });

    await service.deleteCamera('camera-1', owner);

    // KHÔNG DELETE key trên AQP: rotate cho mã cũ hết hiệu lực, key trả về kho để dùng lại.
    expect(order).toEqual(['rotate', 'unlink', 'archive']);
    expect(repository.setAqpStreamKeyId).toHaveBeenCalledWith('camera-1', null);
  });

  it('does not archive a camera while its provider stream is still online', async () => {
    const linkedCamera = { ...camera, aqpStreamKeyId: activeKey.id };
    const { service, repository, agencyClient } = makeService({
      camera: linkedCamera,
      isMediaOnline: jest.fn().mockResolvedValue({ online: true }),
    });

    await expect(service.deleteCamera('camera-1', owner)).rejects.toThrow(
      'Camera đang phát trực tiếp; hãy dừng luồng trước khi xoá camera.',
    );
    expect(agencyClient.rotateStreamKey).not.toHaveBeenCalled();
    expect(repository.setAqpStreamKeyId).not.toHaveBeenCalled();
    expect(repository.deleteCamera).not.toHaveBeenCalled();
  });

  it('unlinks the camera without rotating when AQP no longer has the key at delete time', async () => {
    const linkedCamera = { ...camera, aqpStreamKeyId: activeKey.id };
    const { service, repository, agencyClient } = makeService({
      camera: linkedCamera,
      agency: {
        rotateStreamKey: jest.fn().mockRejectedValue(new AqvisionAgencyApiException('gone', 404)),
      },
    });
    const order: string[] = [];
    (repository.setAqpStreamKeyId as jest.Mock).mockImplementation(async () => {
      order.push('unlink');
      return true;
    });
    repository.deleteCamera.mockImplementation(async () => {
      order.push('archive');
      return linkedCamera;
    });

    await service.deleteCamera('camera-1', owner);

    expect(order).toEqual(['unlink', 'archive']);
    expect(repository.setAqpStreamKeyId).toHaveBeenCalledWith('camera-1', null);
    expect(agencyClient.rotateStreamKey).toHaveBeenCalledTimes(1);
  });

  it('never exposes a deleteStreamKey call site: the agency client pools keys instead', () => {
    const { agencyClient } = makeService();

    // Policy cứng: kho 10 key/agency, DELETE trả key về AQP là mất vĩnh viễn.
    expect(agencyClient).not.toHaveProperty('deleteStreamKey');
  });

  it('revoking surfaces a provider failure and keeps the local link', async () => {
    const linkedCamera = { ...camera, aqpStreamKeyId: activeKey.id };
    const { service, repository } = makeService({
      camera: linkedCamera,
      agency: {
        rotateStreamKey: jest.fn().mockRejectedValue(new AqvisionAgencyApiException('down', 503)),
      },
    });

    await expect(service.revokeCameraAqpStreamKey('camera-1', owner)).rejects.toBeInstanceOf(
      ServiceUnavailableException,
    );
    expect(repository.setAqpStreamKeyId).not.toHaveBeenCalled();
  });

  it('refuses provider operations for PULL cameras or users without tournament access', async () => {
    const pullCamera = { ...camera, mode: 'PULL' };
    const pull = makeService({ camera: pullCamera });
    await expect(pull.service.createCameraAqpStreamKey('camera-1', owner)).rejects.toBeInstanceOf(
      BadRequestException,
    );
    expect(pull.agencyClient.createStreamKey).not.toHaveBeenCalled();

    const privateTournament = makeService({ staff: false });
    await expect(
      privateTournament.service.createCameraAqpStreamKey('camera-1', stranger),
    ).rejects.toBeInstanceOf(ForbiddenException);
    expect(privateTournament.agencyClient.createStreamKey).not.toHaveBeenCalled();
  });

  it('fails without calling AQP when the per-camera distributed lock is unavailable', async () => {
    const { service, agencyClient } = makeService({ lockResult: false });

    await expect(service.createCameraAqpStreamKey('camera-1', owner)).rejects.toBeInstanceOf(
      ServiceUnavailableException,
    );
    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
  });
});

