    expect(agencyClient.createStreamKey).not.toHaveBeenCalled();
  });
  it('rotates the provider key and unlinks it locally before archiving the camera', async () => {
    const linkedCamera = { ...camera, aqpStreamKeyId: activeKey.id };
    const { service, repository, agencyClient } = makeService({ camera: linkedCamera });
    const order: string[] = [];
    agencyClient.rotateStreamKey = jest.fn(async () => {
      order.push('rotate');
      return activeKey;
    });
    (repository.setAqpStreamKeyId as jest.Mock).mockImplementation(async () => {
      order.push('unlink');
      return true;
    });
