    expect(liveAssignmentSql).toContain('"stream_status" = \'LIVE\'');
    expect(
      liveAssignmentSql.match(/"deleted_at"\s+is\s+null/gi) ?? [],
    ).toHaveLength(3);
    expect(
      liveAssignmentSql.match(/"archived_at"\s+is\s+null/gi) ?? [],
    ).toHaveLength(1);
